(function () {
  function MiniSocket() {
    this.handlers = {};
    this.sid = "";
    this.connected = false;
    this.closed = false;
    this.polling = false;
    this.base = "/socket.io/?EIO=4&transport=polling";
    this.open();
  }

  MiniSocket.prototype.on = function (event, handler) {
    if (!this.handlers[event]) {
      this.handlers[event] = [];
    }
    this.handlers[event].push(handler);
    return this;
  };

  MiniSocket.prototype.dispatch = function (event, payload) {
    (this.handlers[event] || []).forEach(function (handler) {
      handler(payload);
    });
  };

  MiniSocket.prototype.post = function (payload) {
    if (!this.sid || this.closed) {
      return Promise.resolve();
    }
    return fetch(this.base + "&sid=" + encodeURIComponent(this.sid), {
      method: "POST",
      headers: { "Content-Type": "text/plain;charset=UTF-8" },
      body: payload
    }).catch(function () {});
  };

  MiniSocket.prototype.emit = function (event, payload) {
    return this.post("42" + JSON.stringify([event, payload || {}]));
  };

  MiniSocket.prototype.open = function () {
    var self = this;
    fetch(this.base + "&t=" + Date.now())
      .then(function (response) {
        if (!response.ok) {
          throw new Error("Socket.IO polling failed");
        }
        return response.text();
      })
      .then(function (text) {
        var openPacket = text.match(/0(\{.*\})/);
        if (!openPacket) {
          throw new Error("Socket.IO open packet missing");
        }
        self.sid = JSON.parse(openPacket[1]).sid;
        return self.post("40");
      })
      .then(function () {
        self.connected = true;
        self.dispatch("connect");
        self.poll();
      })
      .catch(function () {
        self.closed = true;
        self.dispatch("connect_error");
      });
  };

  MiniSocket.prototype.handlePacket = function (packet) {
    if (packet === "2") {
      this.post("3");
      return;
    }
    if (packet.indexOf("42") === 0) {
      try {
        var event = JSON.parse(packet.slice(2));
        this.dispatch(event[0], event[1]);
      } catch (error) {}
    }
  };

  MiniSocket.prototype.poll = function () {
    var self = this;
    if (this.closed || !this.sid || this.polling) {
      return;
    }
    this.polling = true;
    fetch(this.base + "&sid=" + encodeURIComponent(this.sid) + "&t=" + Date.now())
      .then(function (response) {
        if (!response.ok) {
          throw new Error("Socket.IO poll failed");
        }
        return response.text();
      })
      .then(function (text) {
        self.polling = false;
        text.split(/\x1e/).filter(Boolean).forEach(function (packet) {
          self.handlePacket(packet);
        });
        window.setTimeout(function () {
          self.poll();
        }, 20);
      })
      .catch(function () {
        self.polling = false;
        self.closed = true;
        self.connected = false;
        self.dispatch("disconnect");
      });
  };

  MiniSocket.prototype.disconnect = function () {
    this.closed = true;
    this.post("41");
    this.dispatch("disconnect");
  };

  window.io = function () {
    return new MiniSocket();
  };
})();
